	ldb	\A,[\S,0]
	ldb	\B,[\S,1]
	ldb	\C,[\S,2]
	ld.as	\A,[\P,\A]
	ld.as	\B,[\H,\B]
	ld.as	\C,[\P,\C]
	ldb	\E,[\S,3]
	asl	\B,\B,8
	or	\A,\A,\B
	asl	\B,\C,24
	or	\A,\A,\B
	st.di	\A,[\D,0]
	ldb	\F,[\S,4]
	ldb	\G,[\S,5]
	ld.as	\E,[\H,\E]
	ld.as	\F,[\P,\F]
	ld.as	\G,[\H,\G]
	ldb	\A,[\S,6]
	ldb	\B,[\S,7]
	ld.as	\A,[\P,\A]
	ld.as	\B,[\H,\B]
	lsr	\C,\C,8
	or	\C,\C,\E
	asl	\F,\F,16
	or	\C,\C,\F
	asl	\E,\G,24
	or	\C,\C,\E
	add	\S,\S,8
	st.di	\C,[\D,4]
	lsr	\G,\G,8
	asl	\A,\A,8
	or	\G,\G,\A
	asl	\B,\B,16
	or	\G,\G,\B
	sub	\N,\N,1
	st.di	\G,[\D,8]
	add	\D,\D,12
