	bge	xs_next			; off the right
	bmsk	r24,r18,15
	ld	r24,[r5,r24]
	breq	r24,0,xs_tnext
	ror	r24,r24,r12
	bbit1	r13,11,xs_flip
	tst	r21,r21
	bne	xs_nsh
	PNORM	0,12
	PNORM	1,4
	PNORM	2,28
	PNORM	3,20
xs_tnext:
	add	r14,r14,8
	add	r18,r18,r19
	add	r23,r23,4
	b.d	xs_tile
	sub	r15,r15,1
xs_skip:	b.d	xs_next
	mov	r8,0
xs_done:	ld.ab	r24,[sp,4]
	ld.ab	r23,[sp,4]
	ld.ab	r22,[sp,4]
	ld.ab	r21,[sp,4]
	ld.ab	r20,[sp,4]
	ld.ab	r19,[sp,4]
	ld.ab	r18,[sp,4]
	ld.ab	r17,[sp,4]
	ld.ab	r16,[sp,4]
	ld.ab	r15,[sp,4]
	ld.ab	r14,[sp,4]
	ld.ab	r13,[sp,4]
	j	[blink]

xs_flip:	tst	r21,r21
	bne	xs_fnsh
	PNORM	0,16
	PNORM	1,24
	PNORM	2,0
	PNORM	3,8
	b	xs_tnext
xs_nsh:	cmp	r21,1
	bne	xs_mark
	PNONSH	0,12
	PNONSH	1,4
	PNONSH	2,28
	PNONSH	3,20
	b	xs_tnext
xs_mark:
#ifdef SHFAST
	cmp	r21,2
	bhi	xs_shop
#endif
	PMARK	0,12
	PMARK	1,4
	PMARK	2,28
	PMARK	3,20
	b	xs_tnext
xs_fnsh:	cmp	r21,1
	bne	xs_fmark
	PNONSH	0,16
	PNONSH	1,24
	PNONSH	2,0
	PNONSH	3,8
	b	xs_tnext
xs_fmark:
#ifdef SHFAST
	cmp	r21,2
	bhi	xs_fshop
#endif
	PMARK	0,16
	PMARK	1,24
	PMARK	2,0
	PMARK	3,8
	b	xs_tnext

#ifdef SHFAST
xs_shop:	brne	r21,3,xs_only
	PSH	0,12
	PSH	1,4
	PSH	2,28
	PSH	3,20
	b	xs_tnext
xs_only:	PONLYOP	0,12
	PONLYOP	1,4
	PONLYOP	2,28
	PONLYOP	3,20
	b	xs_tnext
xs_fshop: brne	r21,3,xs_fonly
	PSH	0,16
	PSH	1,24
	PSH	2,0
	PSH	3,8
	b	xs_tnext
xs_fonly: PONLYOP	0,16
	PONLYOP	1,24
	PONLYOP	2,0
	PONLYOP	3,8
	b	xs_tnext
#endif

; int arcdraw_ntscan(const u16 *ntrow, int tilex, int xmask, int count):
; number of the count nametable entries with the priority bit, | 0x10000 if the first has it.
	.align 4
	.global arcdraw_ntscan
arcdraw_ntscan:
	and	r12,r1,r2
	ldw.as	r12,[r0,r12]
	mov	r4,0
	lsr	r12,r12,15
	asl	r5,r12,16
1:	and	r12,r1,r2
	ldw.as	r12,[r0,r12]
	add	r1,r1,1
	sub	r3,r3,1
	lsr	r12,r12,15
	brne.d	r3,0,1b
	add	r4,r4,r12
	j.d	[blink]
	or	r0,r4,r5
#endif
